# Code generated by Claude
"""
Re-check the beaker task's staging pose with the camera neck on the robot.

    python experiments/beaker_hotplate_pose_check.py

For every task pose (grasp, above the plate, set-down, ready, and the via waypoint of the arm path) the robot is placed at the
staging pose with the pedestal at its task height and the task arm at that pose's stored joint solution (src/task_config.py),
the beaker at its place or held in the gripper, the neck once at its default aim (drive pose) and once at the pose the framing
function picks for that arm pose. Kinematics only. Reported: the TCP's distance from its target (IK reach), the smallest distance
between the neck and (the task arm, the other arm, the torso, the scene), and between the task arm and the rest of the robot
and the scene (the fingers may touch the held beaker). Distances below 3 mm count as contact. The base footprint is unchanged by the
neck (it is above the torso), so the 8 cm bench clearance and the swept-turn clearance of the staging search still hold.
"""

import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

import beaker_hotplate_layout_search as L  # noqa: E402
from src import robot_specs  # noqa: E402
from src.neck import neck_ids, set_neck_pose  # noqa: E402
from src.neck_framing import frame_points  # noqa: E402
from src.task_beaker_hotplate import load_task, spawn_and_settle, framing_points, yaw_to_quat  # noqa: E402
from src.task_config import TASK_CFG  # noqa: E402

POSE_KEYS = {"grasp": "grasp_q", "above_plate": "above_plate_q", "setdown": "setdown_q", "ready": "ready_q", "via": "ready_via_q"}
CONTACT = 0.003


def main():
    sim = load_task(cameras=True)
    model, data = sim.model, sim.data
    spawn_and_settle(sim)
    z_rest = float(data.qpos[2])
    ctx = L.make_ctx(sim, TASK_CFG["arm"], z_rest)
    g = L.Geo(model)
    neck = neck_ids(model, robot_specs.NECK_SPECS)
    root = ctx.root
    under_neck = lambda b: any(model.body(a).name == robot_specs.NECK_SPECS["prefix"] + "base" for a in _anc(model, b))
    neck_g = [i for i in range(model.ngeom) if under_neck(int(model.geom_bodyid[i])) and (model.geom_contype[i] or model.geom_conaffinity[i])]
    arm_g = ctx.arm_g
    other_arm = {"right" if TASK_CFG["arm"] == "left" else "left"}
    oarm_g = [i for i in range(model.ngeom) if model.body(model.geom_bodyid[i]).name.startswith(f"openarm_{list(other_arm)[0]}_") and model.geom_group[i] == 3]
    torso_g = [i for i in range(model.ngeom) if model.body(model.geom_bodyid[i]).name in ("openarm_body_link0", "pedestal_Top", "pedestal_Middle", "pedestal_Bottom", "base_link")
               and (model.geom_contype[i] or model.geom_conaffinity[i])]
    world_g = ctx.static_other + [ctx.plate_g, ctx.hotbase_g]
    ft = np.zeros(6)

    def mind(A, B, skip=()):
        best, who = 0.05, None
        for a in A:
            for b in B:
                if (a, b) in skip:
                    continue
                dd = mujoco.mj_geomDistance(model, data, a, b, 0.05, ft)
                if dd < best:
                    best, who = dd, (model.geom(a).name or model.body(model.geom_bodyid[a]).name, model.body(model.geom_bodyid[b]).name)
        return best, who

    layout = dict(beaker_xy=TASK_CFG["beaker_xy"], hotplate_xy=TASK_CFG["hotplate_xy"])
    pts = L.task_points(g, layout["beaker_xy"], layout["hotplate_xy"], TASK_CFG["staging_yaw"])
    pts["ready"] = np.array(TASK_CFG["ready_tcp"])
    tcp_body = f"openarm_{TASK_CFG['arm']}_hand_tcp"
    rows, worst = [], 1.0
    print(f"staging pose ({TASK_CFG['staging_xy'][0]:.3f}, {TASK_CFG['staging_xy'][1]:.3f}, {math.degrees(TASK_CFG['staging_yaw']):.0f} deg), pedestal {TASK_CFG['pedestal_q']}, "
          f"{TASK_CFG['arm']} arm, neck mass {sum(model.body_mass[b] for b in range(model.nbody) if model.body(b).name.startswith('neck_')):.3f} kg")
    print(f"{'task pose':12s} {'neck':8s} {'TCP error':>10s}  {'neck-arm':>9s} {'neck-other arm':>14s} {'neck-torso':>10s} {'neck-scene':>10s}  {'arm-rest of robot':>17s} {'arm-scene':>9s}")
    for name, key in POSE_KEYS.items():
        q = TASK_CFG[key]
        finger_q, beaker_origin, held = (L.pose_scene_args(g, name, layout["beaker_xy"], pts[name]) if name in pts else (SEARCH_FINGER, None, False))[0:3] if name != "via" else (0.044, np.array([*layout["beaker_xy"], g.top + 0.002]), False)
        for neck_label in ("drive", "framed"):
            L.set_scene(ctx, TASK_CFG["staging_xy"], TASK_CFG["staging_yaw"], TASK_CFG["pedestal_q"], q, finger_q, beaker_origin, layout["hotplate_xy"])
            set_neck_pose(model, data, robot_specs.NECK_SPECS)
            if neck_label == "framed":
                targets, rep = frame_points(model, data, framing_points(model, data))
                set_neck_pose(model, data, robot_specs.NECK_SPECS, [targets[n] for n in neck["names"]])
            mujoco.mj_collision(model, data)
            err = float(np.linalg.norm(data.body(tcp_body).xpos - pts[name])) if name in pts else float("nan")
            beaker_skip = {(f, ctx.beaker_g) for f in arm_g if f in ctx.finger_g}
            n_arm, w1 = mind(neck_g, arm_g)
            n_oarm, w2 = mind(neck_g, oarm_g)
            n_torso, w3 = mind(neck_g, torso_g)
            n_scene, w4 = mind(neck_g, world_g + [ctx.beaker_g])
            a_rest, w5 = mind(arm_g, torso_g + oarm_g + neck_g)
            a_scene, w6 = mind(arm_g, world_g + [ctx.beaker_g], skip=beaker_skip)
            m = min(n_arm, n_oarm, n_torso, n_scene, a_rest, a_scene)
            worst = min(worst, m)
            fmt = lambda v: f"{1000 * v:7.1f} mm" if v < 0.05 else "   > 50 mm"
            print(f"{name:12s} {neck_label:8s} {1000 * err:8.2f} mm  {fmt(n_arm):>9s} {fmt(n_oarm):>14s} {fmt(n_torso):>10s} {fmt(n_scene):>10s}  {fmt(a_rest):>17s} {fmt(a_scene):>9s}"
                  + ("   <-- CONTACT " + str([w for w in (w1, w2, w3, w4, w5, w6) if w]) if m < CONTACT else ""))
    print(f"\nsmallest distance anywhere in the table: {1000 * worst:.1f} mm ({'no contact' if worst >= CONTACT else 'CONTACT'}; threshold {1000 * CONTACT:.0f} mm)")


def _anc(model, b):
    while b > 0:
        yield b
        b = int(model.body_parentid[b])


if __name__ == "__main__":
    main()
